/// Heap sort — build a max-heap in place, then swap the root to the end and re-sift the rest.
pub fn heap_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    fn sift_down<T: Ord>(a: &mut [T], start: usize, end: usize) {
        let mut root = start;
        loop {
            let left = 2 * root + 1;
            if left > end {
                return;
            }
            let right = left + 1;
            let mut largest = root;
            if a[largest] < a[left] {
                largest = left;
            }
            if right <= end && a[largest] < a[right] {
                largest = right;
            }
            if largest == root {
                return;
            }
            a.swap(root, largest);
            root = largest;
        }
    }
    let mut out = xs.to_vec();
    let n = out.len();
    if n < 2 {
        return out;
    }
    for start in (0..n / 2).rev() {
        sift_down(&mut out, start, n - 1);
    }
    for end in (1..n).rev() {
        out.swap(0, end);
        sift_down(&mut out, 0, end - 1);
    }
    out
}
